#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int n; cin >> n;
    vector<int> starts(n), ends(n);
    for (int i = 0; i < n; i++) cin >> starts[i] >> ends[i];
    sort(starts.begin(), starts.end());
    sort(ends.begin(), ends.end());
    int q; cin >> q;
    while (q--) {
        int p; cin >> p;
        // intervals containing p: those with start <= p AND end >= p
        int cnt_start = upper_bound(starts.begin(), starts.end(), p) - starts.begin();
        int cnt_end   = lower_bound(ends.begin(),   ends.end(),   p) - ends.begin();
        cout << cnt_start - cnt_end << "\n";
    }
    return 0;
}

