import java.util.*;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] starts = new int[n], ends = new int[n];
        for (int i = 0; i < n; i++) { starts[i] = sc.nextInt(); ends[i] = sc.nextInt(); }
        Arrays.sort(starts);
        Arrays.sort(ends);
        int q = sc.nextInt();
        while (q-- > 0) {
            int p = sc.nextInt();
            // starts <= p
            int lo = 0, hi = n;
            while (lo < hi) { int mid=(lo+hi)/2; if (starts[mid]<=p) lo=mid+1; else hi=mid; }
            int cntS = lo;
            // ends < p
            lo = 0; hi = n;
            while (lo < hi) { int mid=(lo+hi)/2; if (ends[mid]<p) lo=mid+1; else hi=mid; }
            int cntE = lo;
            System.out.println(cntS - cntE);
        }
    }
}
